import unittest
import csv_field as app

class Behavior(unittest.TestCase):
    def test_fields(self):
        cases = [('', ''), ('fjord', 'fjord'), (' dock ', ' dock '),
                 ('A,B', '"A,B"'), ('say "yes"', '"say ""yes"""'),
                 ('a\r\nb', '"a\r\nb"'), ('a\rb', '"a\rb"'),
                 ('a\nb', '"a\nb"'), ('"', '""""'), (',"\n', '",""\n"')]
        for value, expected in cases:
            with self.subTest(value=value):
                self.assertEqual(app.encode_field(value), expected)

if __name__ == '__main__':
    unittest.main()

